{
  "assessment": "Niger faces persistent domestic protests alongside a mixed mood among the military and security services, indicating latent coup risks. With a budget deficit of 4.2% and inflation at 8.4%, we must maintain strict fiscal discipline while easing popular pressure through targeted welfare and economic reforms. We will continue our current repressive and controlled media posture to maintain order, but implement reforms to appease the public. We must also consolidate our position within the Alliance of Sahel States (AES) and maintain strong ties with our regional partners.",
  "directives": [
    {
      "type": "reforms",
      "target": null,
      "amount": 0.2,
      "sub": "",
      "order": "Implement administrative and anti-corruption reforms to ease public discontent and address root causes of protests."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.0,
      "sub": "welfare",
      "order": "Increase welfare spending to 2.0% of GDP to support vulnerable urban populations and youth."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": -0.5,
      "sub": "",
      "order": "Lower the policy rate by 0.5 percentage points to stimulate economic activity and ease inflationary pressure."
    },
    {
      "type": "purge",
      "target": null,
      "amount": 0,
      "sub": "military",
      "order": "Conduct a limited purge of potentially disloyal elements within the senior officer corps to safeguard the regime."
    }
  ],
  "cables": [
    {
      "to": "MLI",
      "private": true,
      "text": "Greetings from Niamey. We reaffirm our commitment to the Alliance of Sahel States and mutual security cooperation."
    },
    {
      "to": "BFA",
      "private": true,
      "text": "In light of regional challenges, Niger proposes closer intelligence sharing and joint security coordination."
    }
  ],
  "public_statement": "The Government of Niger remains firmly committed to restoring stability, promoting economic development, and ensuring the security of all citizens. We are implementing meaningful reforms to address the grievances of our people while standing resolute against internal and external threats.",
  "standing_orders": [
    {
      "when": "coup_risk_high",
      "do": {
        "type": "purge",
        "target": null,
        "amount": 0,
        "sub": "military",
        "order": "Intensify security vetting and purge disloyal elements from the military."
      }
    },
    {
      "when": "unrest_at_least:protests",
      "do": {
        "type": "repression_level",
        "target": null,
        "amount": 0.7,
        "sub": "",
        "order": "Maintain high security posture against illegal protests."
      }
    }
  ],
  "detailed_report": "economy"
}
